
// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

/**
 * A URL is only used by commands that touch the database (migrate, studio).
 * `prisma generate` runs from `postinstall`, so it also runs on CI runners and
 * clean installs where no connection string exists. Prisma's `env()` helper
 * throws while loading this config when a variable is missing — even inside
 * `??` — which failed `npm ci` and therefore every workflow. Read the
 * variables directly and fall back to a placeholder: generate then succeeds
 * anywhere, and a migrate run without real credentials fails to connect
 * rather than failing to load the config.
 */
const datasourceUrl =
  process.env.DIRECT_URL ??
  process.env.DATABASE_URL ??
  "postgresql://placeholder:placeholder@localhost:5432/glance";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  engine: "classic",
  datasource: {
    // Migrations need a direct-style session (prepared statements survive);
    // the pooled runtime URL is fine for the app but not for the schema engine.
    url: datasourceUrl,
  },
});
